32 holographChainId) external; function getInterfaces() external view returns (address interfaces); function setInterfaces(address interfaces) external; function getOperator() external view returns (address operator); function setOperator(address operator) external; function getRegistry() external view returns (address registry); function setRegistry(address registry) external; function getTreasury() external view returns (address treasury); function setTreasury(address treasury) external; function getUtilityToken() external view returns (address utilityToken); function setUtilityToken(address utilityToken) external; } contract Holograph is Admin, Initializable, HolographInterface { bytes32 constant _bridgeSlot = 0xeb87cbb21687feb327e3d58c6c16d552231d12c7a0e8115042a4165fac8a77f9; bytes32 constant _chainIdSlot = 0x7651bfc11f7485d07ab2b41c1312e2007c8cb7efb0f7352a6dee4a1153eebab2; bytes32 constant _factorySlot = 0xa49f20855ba576e09d13c8041c8039fa655356ea27f6c40f1ec46a4301cd5b23; bytes32 constant _holographChainIdSlot = 0xd840a780c26e07edc6e1ee2eaa6f134ed5488dbd762614116653cee8542a3844; bytes32 constant _interfacesSlot = 0xbd3084b8c09da87ad159c247a60e209784196be2530cecbbd8f337fdd1848827; bytes32 constant _operatorSlot = 0x7caba557ad34138fa3b7e43fb574e0e6cc10481c3073e0dffbc560db81b5c60f; bytes32 constant _registrySlot = 0xce8e75d5c5227ce29a4ee170160bb296e5dea6934b80a9bd723f7ef1e7c850e7; bytes32 constant _treasurySlot = 0x4215e7a38d75164ca078bbd61d0992cdeb1ba16f3b3ead5944966d3e4080e8b6; bytes32 constant _utilityTokenSlot = 0xbf76518d46db472b71aa7677a0908b8016f3dee568415ffa24055f9a670f9c37; constructor() {} function init(bytes memory initPayload) external override returns (bytes4) { require(!_isInitialized(), "HOLOGRAPH: already initialized"); ( uint32 holographChainId, address bridge, address factory, address interfaces, address operator, address registry, address treasury, address utilityToken ) = abi.decode(initPayload, (uint32, address, address, address, address, addre