Contract, uint256 gasLimit, uint256 gasPrice, bytes calldata bridgeOutPayload ) external returns (bytes memory samplePayload); function getMessageFee( uint32 toChain, uint256 gasLimit, uint256 gasPrice, bytes calldata crossChainPayload ) external view returns (uint256 hlgFee, uint256 msgFee); function getFactory() external view returns (address factory); function setFactory(address factory) external; function getHolograph() external view returns (address holograph); function setHolograph(address holograph) external; function getJobNonce() external view returns (uint256 jobNonce); function getOperator() external view returns (address operator); function setOperator(address operator) external; function getRegistry() external view returns (address registry); function setRegistry(address registry) external; } struct DeploymentConfig { bytes32 contractType; uint32 chainType; bytes32 salt; bytes byteCode; bytes initCode; } struct Verification { bytes32 r; bytes32 s; uint8 v; } interface HolographFactoryInterface { event BridgeableContractDeployed(address indexed contractAddress, bytes32 indexed hash); function deployHolographableContract( DeploymentConfig memory config, Verification memory signature, address signer ) external; function getHolograph() external view returns (address holograph); function setHolograph(address holograph) external; function getRegistry() external view returns (address registry); function setRegistry(address registry) external; } struct OperatorJob { uint8 pod; uint16 blockTimes; address operator; uint40 startBlock; uint64 startTimestamp; uint16[5] fallbackOperators; } interface HolographOperatorInterface { event AvailableOperatorJob(bytes32 jobHash, bytes payload); event CrossChainMessageSent(bytes32 messageHash); event FailedOperatorJob(bytes32 jobHash); function executeJob(bytes calldata bridgeInRequestPayload) external payable; function nonRevertingBridgeCall(address msgSender, bytes calldata payload) external payable; function crossChainMessage(bytes calldata bridgeInRequestPayload) external payable; function jobEstimator(bytes calldata bridgeInRequestPayload) external payable returns (uint256); function send( uint256 gasLimit, uint256 gasPrice, uint32 toChain, address msgSender, uint256 nonce, address holographableContract, bytes calldata bridgeOutPayload ) external payable; function getMessageFee( uint32 toChain, uint256 gasLimit, uint256 gasPrice, bytes calldata crossChainPayload ) external view returns (uint256 hlgFee, uint256 msgFee); function getJobDetails(bytes32 jobHash) external view returns (OperatorJob memory); function getTotalPods() external view returns (uint256 totalPods); function getPodOperatorsLength(uint256 pod) external view returns (uint256); function getPodOperators(uint256 pod) external view returns (address[] memory operators); function getPodOperators( uint256 pod, uint256 index, uint256 length ) external view returns (address[] memory operators); function getPodBondAmounts(uint256 pod) external view returns (uint256 base, uint256 current); function getBondedAmount(address operator) external view returns (uint256 amount); function getBondedPod(address operator) external view returns (uint256 pod); function topupUtilityToken(address operator, uint256 amount) external; function bondUtilityToken( address operator, uint256 amount, uint256 pod ) external; function unbondUtilityToken(address operator, address recipient) external; function getBridge() external view returns (address bridge); function setBridge(address bridge) external; function getHolograph() external view returns (address holograph); function setHolograph(address holograph) external; function getInterfaces() external view returns (address interfaces); function setInterfaces(address interfaces) external; function getMessagingModule() external view returns (address messagingModule); function setMessagingModule(address messagingModule) external; function getRegistry() external view returns (address registry); function setRegistry(address registry) external; function getUtilityToken() external view returns (address utilityToken); function setUtilityToken(address utilityToken) external; } interface HolographRegistryInterface { function isHolographedContract(address smartContract) external view returns (bool); function isHolographedHashDeployed(bytes32 hash) external view returns (bool); function referenceContractTypeAddress(address contractAddress) external returns (bytes32); function getContractTypeAddress(bytes32 contractType) external view returns (address); function setContractTypeAddress(bytes32 contractType, address contractAddress) external; function getHolograph() external view returns (address holograph); function setHolograph(address holograph) external; function getHolographableContracts(uint256 index, uint256 length) external view returns (address[] memory contracts); function getHolographableContractsLength() external view returns (uint256); function getHolographedHashAddress(bytes32 hash) external view returns (address); function setHolographedHashAddress(bytes32 hash, address contractAddress) external; function getHToken(uint32 chainId) external view returns (address); function setHToken(uint32 chainId, address hToken) external; function getReservedContractTypeAddress(bytes32 contractType) external view returns (address contractTypeAddress); function setReservedContractTypeAddress(bytes32 hash, bool reserved) external; function setReservedContractTypeAddresses(bytes32[] calldata hashes, bool[] calldata reserved) external; function getUtilityToken() external view returns (address utilityToken); function setUtilityToken(address utilityToken) external; } contract HolographBridge is Admin, Initializable, HolographBridgeInterface { bytes32 constant _factorySlot = 0xa49f20855ba576e09d13c8041c8039fa655356ea27f6c40f1ec46a4301cd5b23; bytes32 constant _holographSlot = 0xb4107f746e9496e8452accc7de63d1c5e14c19f510932daa04077cd49e8bd77a; bytes32 constant _jobNonceSlot = 0x1cda6480