not holographed" ); (bytes4 selector, bytes memory returnedPayload) = Holographable(holographableContract).bridgeOut( toChain, msg.sender, bridgeOutPayload ); require(selector == Holographable.bridgeOut.selector, "HOLOGRAPH: bridge out failed"); _operator().send{value: msg.value}( gasLimit, gasPrice, toChain, msg.sender, _jobNonce(), holographableContract, returnedPayload ); } function revertedBridgeOutRequest( address sender, uint32 toChain, address holographableContract, bytes calldata bridgeOutPayload ) external returns (string memory revertReason) { try Holographable(holographableContract).bridgeOut(toChain, sender, bridgeOutPayload) returns ( bytes4 selector, bytes memory payload ) { if (selector != Holographable.bridgeOut.selector) { return "HOLOGRAPH: bridge out failed"; } assembly { revert(add(payload, 0x20), mload(payload)) } } catch Error(string memory reason) { return reason; } catch { return "HOLOGRAPH: unknown error"; } } function getBridgeOutRequestPayload( uint32 toChain, address holographableContract, uint256 gasLimit, uint256 gasPrice, bytes calldata bridgeOutPayload ) external returns (bytes memory samplePayload) { require( _registry().isHolographedContract(holographableContract) || address(_factory()) == holographableContract, "HOLOGRAPH: not holographed" ); bytes memory payload; try this.revertedBridgeOutRequest(msg.sender, toChain, holographableContract, bridgeOutPayload) returns ( string memory revertReason ) { revert(revertReason); } catch (bytes memory realResponse) { payload = realResponse; } uint256 jobNonce; assembly { jobNonce := sload(_jobNonceSlot) } uint256 fee = 0; if (gasPrice < type(uint256).max && gasLimit < type(uint256).max) { (uint256 hlgFee, ) = _operator().getMessageFee(toChain, gasLimit, gasPrice, bridgeOutPayload); fee = hlgFee; } bytes memory encodedData = abi.encodeWithSelector( HolographBridgeInterface.bridgeInRequest.selector, jobNonce + 1, _holograph().getHolographChainId(), holographableContract, _registry().getHToken(